"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["29173"],{75245(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>p,contentTitle:()=>d,toc:()=>h,assets:()=>c});var a=JSON.parse('{"id":"nhcx/v1/api/other/endpoints/other-v1-on-status","title":"Recipient: answer a status check","description":"The answer to a status request, delivered to the sender that asked. The x-hcx-status in the protected header says where the message you asked about got to....","source":"@site/docs/nhcx/v1/api/other/endpoints/other-v1-on-status.mdx","sourceDirName":"nhcx/v1/api/other/endpoints","slug":"/nhcx/v1/api/other/endpoints/other-v1-on-status","permalink":"/docs/pr-49/docs/nhcx/v1/api/other/endpoints/other-v1-on-status","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Recipient: answer a status check","sidebar_label":"Recipient: answer a status check","sidebar_class_name":"api-method api-method--post","description":"The answer to a status request, delivered to the sender that asked. The x-hcx-status in the protected header says where the message you asked about got to....","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-other.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Support: delete records by correlation ID","permalink":"/docs/pr-49/docs/nhcx/v1/api/other/endpoints/other-v1-delete"},"next":{"title":"NHCX: report a request it could not deliver","permalink":"/docs/pr-49/docs/nhcx/v1/api/other/endpoints/other-v1-error"}}'),s=n(62540),r=n(43023),o=n(74693),i=JSON.parse('{"id":"other_v1_on_status","module":"Other","moduleId":"other","kind":"operation","method":"POST","path":"/v1/on_status","server":"https://apisbx.abdm.gov.in/hcx","servers":[{"url":"https://apisbx.abdm.gov.in/hcx","description":"Sandbox, NHCX exchange."},{"url":"https://apisprod.nha.gov.in/hcx","description":"Production."}],"summary":"Recipient: answer a status check","title":"Recipient: answer a status check","description":"The answer to a status request, delivered to the sender that asked. The `x-hcx-status` in the protected header says where the message you asked about got to. The payload is an empty string.\\n\\n### Business purpose\\n\\nIt separates \\"did my message arrive\\" from \\"what did the payer decide\\". A sender learns whether a quiet case is still held by the exchange, has reached the recipient, or is dead, without resubmitting it and creating a duplicate.\\n\\n### When to use\\n\\nEvery participant that sends `/v1/status` hosts this path. It carries the answer to your status request.\\n\\n### Preconditions\\n\\n- You sent `/v1/status` and kept track of which request it asked about.\\n- Your callback URL is registered and answers `202` within 30 seconds.\\n\\n### Postconditions\\n\\nRead `x-hcx-status` in the header. `request.dispatched` means the message reached the recipient, and `request.queued` means NHCX still holds it. `request.stopped` means the request is dead, so a retry needs a new correlation ID. Answer `202`.\\n\\n### Common mistakes\\n\\n- Expecting a bundle. The payload is an empty string.\\n- Matching on the original request\'s correlation ID instead of your status request\'s.\\n- Retrying a stopped request on its old correlation ID.\\n\\n### Best practices\\n\\n- Keep every `API_call_ID` you send. Without it you cannot ask the question at all.\\n- Act on `request.stopped` at once, and treat `request.dispatched` as a reason to wait for the payer.\\n- Ask from a support screen when a case has gone quiet for longer than the payer\'s expected turnaround, not on a timer.\\n\\n### Related scenario\\n\\nA pre-authorisation has had no answer for longer than the payer\'s usual turnaround. The support screen sends `/v1/status` with that request\'s `API_call_ID` as the correlation ID. The answer arrives here with an empty payload and `x-hcx-status` `request.stopped`, so the desk knows the request is dead rather than slow, and resubmits it with a fresh correlation ID.\\n\\n### Specification\\n\\nChapter [NHCX adapter (Optional)](/docs/nhcx/v1/getting-started/nhcx-adapter) of the NHCX integration specification.","gateway":"nhcx","security":[{"name":"bearerAuth","type":"apiKey","in":"header","headerName":"bearer_auth","description":"Every NHCX call carries the access token from the session call in a header named `bearer_auth`, as the word `Bearer`, a space and the token. NHCX reads `bearer_auth`, not `Authorization`.","example":"Bearer <access token>","prefix":"Bearer "}],"headers":[],"pathParams":[],"queryParams":[],"body":[{"name":"type","type":"string","required":true,"description":"Always `JWEPayload`. Every response (`on_`) call sends it beside `payload`.","enum":["JWEPayload"],"encrypted":false,"fixed":"JWEPayload"},{"name":"payload","type":"string","required":true,"description":"","encrypted":false}],"requestExample":{"type":"JWEPayload","payload":"<compact JWE>"},"protectedHeader":[{"name":"alg","type":"string","required":true,"description":"Key management algorithm. Always `RSA-OAEP-256`: the content key is wrapped with the recipient\'s RSA public key.","example":"RSA-OAEP-256"},{"name":"enc","type":"string","required":true,"description":"Content encryption algorithm. Always `A256GCM`.","example":"A256GCM"},{"name":"x-hcx-sender_code","type":"string","required":true,"description":"Your participant code. Mandatory on the envelope.","example":"<participant code>"},{"name":"x-hcx-recipient_code","type":"string","required":true,"description":"The recipient\'s. For a provider, the processor code from the policy lookup. Mandatory on the envelope.","example":"<recipient code>"},{"name":"x-hcx-api_call_id","type":"string","required":true,"description":"Fresh on every message, including responses. Mandatory on the envelope.","example":"<uuid>"},{"name":"x-hcx-correlation_id","type":"string","required":true,"description":"The thread that ties a request to its answers. [The correlation ID rule](/docs/nhcx/v1/reference/envelope-fields#the-correlation-id-rule-in-full) says when to reuse it. Mandatory on the envelope.","example":"<correlation id>"},{"name":"x-hcx-timestamp","type":"string","required":true,"description":"The time the message was made. [Timestamp](/docs/nhcx/v1/reference/envelope-fields#timestamp) gives the format. Mandatory on the envelope.","example":"<iso timestamp>"},{"name":"x-hcx-status","type":"string","required":true,"description":"Where this message stands. [Status words](/docs/nhcx/v1/reference/envelope-fields#status-words) lists the values. Mandatory on the envelope.","example":"response.complete"}],"responses":[{"status":"200","description":"Read `x-hcx-status` from the protected header.","example":{"timestamp":"19/03/2026 11:46:35:120","api_call_id":"{{$guid}}","correlation_id":"{{correlationId}}","error":{"code":"","message":""}},"synthesised":false,"fields":[{"name":"timestamp","type":"string","required":false,"description":""},{"name":"api_call_id","type":"string","required":false,"description":""},{"name":"correlation_id","type":"string","required":false,"description":""},{"name":"error","type":"object","required":false,"description":""},{"name":"error.code","type":"string","required":false,"description":""},{"name":"error.message","type":"string","required":false,"description":""}]}],"curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/on_status \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"type\\": \\"JWEPayload\\",\\n  \\"payload\\": \\"<compact JWE>\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/hcx/v1/on_status \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"type\\": \\"JWEPayload\\",\\n  \\"payload\\": \\"<compact JWE>\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/hcx/v1/on_status\\",\\n    headers={\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"type\\": \\"JWEPayload\\",\\n        \\"payload\\": \\"<compact JWE>\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node.js","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/hcx/v1/on_status\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"type\\": \\"JWEPayload\\",\\n    \\"payload\\": \\"<compact JWE>\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"},{"id":"java","label":"Java","language":"java","code":"import java.net.URI;\\nimport java.net.http.HttpClient;\\nimport java.net.http.HttpRequest;\\nimport java.net.http.HttpResponse;\\n\\nHttpClient client = HttpClient.newHttpClient();\\nHttpRequest request = HttpRequest.newBuilder()\\n    .uri(URI.create(\\"https://apisbx.abdm.gov.in/hcx/v1/on_status\\"))\\n    .header(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n    .header(\\"Content-Type\\", \\"application/json\\")\\n    .method(\\"POST\\", HttpRequest.BodyPublishers.ofString(\\"\\"\\"\\n        {\\n            \\"type\\": \\"JWEPayload\\",\\n            \\"payload\\": \\"<compact JWE>\\"\\n        }\\n        \\"\\"\\"))\\n    .build();\\n\\nHttpResponse<String> response = client.send(request, HttpResponse.BodyHandlers.ofString());\\nSystem.out.println(response.statusCode() + \\" \\" + response.body());"},{"id":"php","label":"PHP","language":"php","code":"<?php\\n\\n$ch = curl_init(\'https://apisbx.abdm.gov.in/hcx/v1/on_status\');\\ncurl_setopt_array($ch, [\\n    CURLOPT_CUSTOMREQUEST => \'POST\',\\n    CURLOPT_RETURNTRANSFER => true,\\n    CURLOPT_HTTPHEADER => [\\n        \'bearer_auth: Bearer <access token>\',\\n        \'Content-Type: application/json\',\\n    ],\\n    CURLOPT_POSTFIELDS => <<<\'JSON\'\\n    {\\n        \\"type\\": \\"JWEPayload\\",\\n        \\"payload\\": \\"<compact JWE>\\"\\n    }\\n    JSON,\\n]);\\n\\n$response = curl_exec($ch);\\necho curl_getinfo($ch, CURLINFO_HTTP_CODE), \' \', $response, PHP_EOL;"},{"id":"go","label":"Go","language":"go","code":"package main\\n\\nimport (\\n\\t\\"fmt\\"\\n\\t\\"io\\"\\n\\t\\"net/http\\"\\n\\t\\"strings\\"\\n)\\n\\nfunc main() {\\n\\tbody := strings.NewReader(`{\\n  \\"type\\": \\"JWEPayload\\",\\n  \\"payload\\": \\"<compact JWE>\\"\\n}`)\\n\\treq, err := http.NewRequest(\\"POST\\", \\"https://apisbx.abdm.gov.in/hcx/v1/on_status\\", body)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\treq.Header.Set(\\"bearer_auth\\", \\"Bearer <access token>\\")\\n\\treq.Header.Set(\\"Content-Type\\", \\"application/json\\")\\n\\n\\tresp, err := http.DefaultClient.Do(req)\\n\\tif err != nil {\\n\\t\\tpanic(err)\\n\\t}\\n\\tdefer resp.Body.Close()\\n\\tout, _ := io.ReadAll(resp.Body)\\n\\tfmt.Println(resp.StatusCode, string(out))\\n}"},{"id":"csharp","label":"C#","language":"csharp","code":"using var client = new HttpClient();\\nvar request = new HttpRequestMessage(new HttpMethod(\\"POST\\"), \\"https://apisbx.abdm.gov.in/hcx/v1/on_status\\");\\nrequest.Headers.TryAddWithoutValidation(\\"bearer_auth\\", \\"Bearer <access token>\\");\\nrequest.Content = new StringContent(\\"\\"\\"\\n    {\\n        \\"type\\": \\"JWEPayload\\",\\n        \\"payload\\": \\"<compact JWE>\\"\\n    }\\n    \\"\\"\\", System.Text.Encoding.UTF8, \\"application/json\\");\\n\\nvar response = await client.SendAsync(request);\\nConsole.WriteLine($\\"{(int)response.StatusCode} {await response.Content.ReadAsStringAsync()}\\");"},{"id":"ruby","label":"Ruby","language":"ruby","code":"require \'net/http\'\\n\\nuri = URI(\'https://apisbx.abdm.gov.in/hcx/v1/on_status\')\\nrequest = Net::HTTP::Post.new(uri)\\nrequest[\'bearer_auth\'] = \'Bearer <access token>\'\\nrequest[\'Content-Type\'] = \'application/json\'\\nrequest.body = <<~\'JSON\'\\n  {\\n    \\"type\\": \\"JWEPayload\\",\\n    \\"payload\\": \\"<compact JWE>\\"\\n  }\\nJSON\\n\\nresponse = Net::HTTP.start(uri.hostname, uri.port, use_ssl: uri.scheme == \'https\') do |http|\\n  http.request(request)\\nend\\nputs response.code, response.body"}]}');let p={title:"Recipient: answer a status check",sidebar_label:"Recipient: answer a status check",sidebar_class_name:"api-method api-method--post",description:"The answer to a status request, delivered to the sender that asked. The x-hcx-status in the protected header says where the message you asked about got to....",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-other.yaml",generated:!0},d,c={},h=[{value:"Callbacks",id:"callbacks",level:2}];function l(e){let t={a:"a",code:"code",h2:"h2",li:"li",ul:"ul",...(0,r.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.A,{operation:i}),"\n",(0,s.jsx)(t.h2,{id:"callbacks",children:"Callbacks"}),"\n",(0,s.jsxs)(t.ul,{children:["\n",(0,s.jsxs)(t.li,{children:["NHCX delivers this call to the participant, on the participant's own ",(0,s.jsx)(t.code,{children:"/v1/on_status"}),", not back to you. ",(0,s.jsx)(t.a,{href:"/docs/nhcx/v1/api/other/endpoints/other-webhook-v1-on-status",children:"Sender receives the status answer"}),"."]}),"\n"]})]})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,s.jsx)(t,{...e,children:(0,s.jsx)(l,{...e})}):l(e)}}}]);